// Edit, then undo. The buttons call the same store.undo()/redo() the
// code above calls. Note what a WRITE after an undo does: the redo entries
// are dropped — a history is a line, not a tree — so the count can go down.
function Editor() {
  const n = store.usePath('/n')
  const label = store.usePath('/label')
  const [, tick] = useReducer((x) => x + 1, 0)
  return (
    <div className="rowd" style={{ gap: 8, flexWrap: 'wrap' }}>
      <input className="pg-input" style={{ width: 120 }} value={label}
        onChange={(e) => setLabel(e.target.value)} />
      <input className="pg-input" style={{ width: 70 }} type="number" value={n}
        onChange={(e) => setN(Number(e.target.value))} />
      <button className="tab" onClick={() => { store.undo(); tick() }} disabled={!store.canUndo}>undo</button>
      <button className="tab" onClick={() => { store.redo(); tick() }} disabled={!store.canRedo}>redo</button>
      <span className="lnote">{store.log.length} in the log · cursor {store.cursor + 1}</span>
    </div>
  )
}
return <Editor />
